using System;
using System.IO;
using System.IO.Compression;

namespace Njulf.Rendering.Resources
{
    /// <summary>
    /// Canonical 64x64 RGBA16F LTC lookup payloads fitted by Eric Heitz.
    /// The original DDS headers are intentionally omitted; only tightly packed
    /// texels are retained so upload does not depend on a DDS decoder.
    /// </summary>
    internal static class LtcLookupTableData
    {
        public const uint Size = 64;
        public const int PayloadSize = 64 * 64 * 8;

        private static readonly byte[] MatrixPayload = Decode(MatrixGzipBase64);
        private static readonly byte[] AmplitudePayload = Decode(AmplitudeGzipBase64);

        public static ReadOnlySpan<byte> Matrix => MatrixPayload;
        public static ReadOnlySpan<byte> Amplitude => AmplitudePayload;

        private static byte[] Decode(string encoded)
        {
            byte[] compressed = Convert.FromBase64String(encoded);
            using var source = new MemoryStream(compressed, writable: false);
            using var gzip = new GZipStream(source, CompressionMode.Decompress);
            using var destination = new MemoryStream(PayloadSize);
            gzip.CopyTo(destination);
            byte[] payload = destination.ToArray();
            if (payload.Length != PayloadSize)
            {
                throw new InvalidDataException(
                    $"LTC payload has {payload.Length} bytes; expected {PayloadSize}.");
            }

            return payload;
        }

